def source(repo, path, entity=None):
    name = 'tensorflow' if repo == 'tensorflow/tensorflow' else 'keras'
    rev = TF if name == 'tensorflow' else K
    p = ROOT / 'source' / name / path
    b = p.read_bytes()
    result = {'repository': repo, 'revision': rev, 'path': path, 'sha256': hashlib.sha256(b).hexdigest(), 'url': f'https://github.com/{repo}/blob/{rev}/{path}'}
    if entity:
        nodes = ast.parse(b).body
        n = None
        for part in entity.split('.'):
            n = next((x for x in nodes if isinstance(x, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)) and x.name == part))
            nodes = n.body
        result.update({'entity': entity, 'line': n.lineno, 'end_line': n.end_lineno, 'url': result['url'] + f'#L{n.lineno}', 'docstring_sha256': hashlib.sha256((ast.get_docstring(n) or '').encode()).hexdigest()})
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            result['signature'] = ast.unparse(n.args)
    return result
